func addressAllowed(addr netip.Addr, fixture bool) bool {
	addr = addr.Unmap()
	if addr.IsLoopback() {
		return fixture && addr == netip.MustParseAddr("127.0.0.1")
	}
	if !addr.IsGlobalUnicast() || addr.IsPrivate() || addr.IsLinkLocalUnicast() {
		return false
	}
	for _, prefix := range []string{"0.0.0.0/8", "100.64.0.0/10", "192.0.0.0/24", "192.0.2.0/24", "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "2001::/23", "2002::/16", "64:ff9b::/96", "64:ff9b:1::/48"} {
		if netip.MustParsePrefix(prefix).Contains(addr) {
			return false
		}
	}
	// This fixture is not a complete IANA special-address policy. Production
	// must reuse and qualify LSF's full policy, including future registry changes.
	return true
}
